        "output": "\section{A rational labelled orbit census}
Let $c_{s,p}$ be the number of orbits on all cores with a fixed $s$-element
label set and exact period $p$, divided by $s!$, and let
$C(t,q)=\sum_{s,p}c_{s,p}t^sq^p$. Thus $t$ is an exponential-generating
variable for labels and $q$ marks the actual period, not an upper bound.
Write $\fall{n}{s}=n!/(n-s)!$.

\begin{theorem}\label{thm:census}
Set $x=tq^2$, $Q=x/(1-x)$ and $D=(1-x)^{-2}-(1+x)^2$. Then
\begin{align}
 C_8(t,q)&=tq+t^2q^3+\tfrac12t^3q^4+\tfrac14tq^4D,\label{eq:c8}\\
 C_B(t,q)&=\frac{t^2q^4(1+tq)^2}{2(1-tq^2)}
          +\frac{t^2q^8D}{4(1-tq^4)},\label{eq:cb}\\
 C_\Theta(t,q)&=\tfrac12t^2q^2+
       \tfrac12t^2q^6\left(Q+Q^2+\tfrac13Q^3\right),\label{eq:ct}\\
 C(t,q)&=C_8(t,q)+C_B(t,q)+C_\Theta(t,q).
\end{align}
The number $o(n,p)$ of full-carrier orbits of exact period $p$ is
\begin{equation}\label{eq:full}
 o(n,p)=\sum_{s=1}^n\fall{n}{s}\,n^{n-s}[t^sq^p]C(t,q).
\end{equation}
Moreover
\begin{equation}\label{eq:cscalar}
 C(t,1)=\frac{t-t^2+t^4/2-t^5/12}{(1-t)^3},\qquad
 c_1=1,\ c_2=2,\ c_s=\frac{5s^2+s+24}{24}\quad(s\ge3),
\end{equation}
where $c_s=[t^s]C(t,1)$. Consequently the total orbit count is the
